{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례상 동네 금연거리 구간 축소 시 변경 구간(어디부터 어디까지)을 처음 지정 시와 같이 공식적으로 공지해야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "금연구역의 지정 변경 또는 해제에 관한 사항은 제5조제2항과 제5조제3항을 준용하므로, 구간을 줄이는 변경도 지정 시와 마찬가지로 그 취지 및 장소와 범위에 대하여 서울특별시보에 고시하여야 한다. 따라서 변경 구간(어디부터 어디까지)을 공식적으로 공지해야 한다.",
          "b_ids": "금연:제6조제2항, 금연:제5조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
